-- Audit Triggers Migration for engagement module
-- Generated by metaphor-schema
--
-- This migration adds automatic timestamp management triggers
-- to all tables with audit metadata fields.
--
-- Triggers automatically set:
--   - metadata->'created_at' on INSERT
--   - metadata->'updated_at' on INSERT and UPDATE

-- ==============================================================================
-- Table: EngagementLinkTracker (engagement.engagement_link_trackers)
-- ==============================================================================

-- Function to set metadata timestamps
CREATE OR REPLACE FUNCTION engagement.engagement_link_trackers_audit_timestamp() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{created_at}', to_jsonb(NOW()));
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS engagement_link_trackers_insert_audit ON engagement.engagement_link_trackers;
CREATE TRIGGER engagement_link_trackers_insert_audit BEFORE INSERT ON engagement.engagement_link_trackers
    FOR EACH ROW EXECUTE FUNCTION engagement.engagement_link_trackers_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS engagement_link_trackers_update_audit ON engagement.engagement_link_trackers;
CREATE TRIGGER engagement_link_trackers_update_audit BEFORE UPDATE ON engagement.engagement_link_trackers
    FOR EACH ROW EXECUTE FUNCTION engagement.engagement_link_trackers_audit_timestamp();

